BEGIN;

-- 1. School
VALUES ('10000000-0000-4000-8000-000000000001', 'Schoolic Portfolio Academy', 'PORTFOLIO', now())
ON CONFLICT (id) DO UPDATE SET
  name = excluded.name,
  code = excluded.code,
  updated_at = now();

-- 2. Academic Year
ON CONFLICT (id) DO UPDATE SET
  name = excluded.name,
  starts_on = excluded.starts_on,
  ends_on = excluded.ends_on,
  is_active = excluded.is_active,
  updated_at = now();

-- 3. Classes
ON CONFLICT (id) DO UPDATE SET
  name = excluded.name,
  sort_order = excluded.sort_order,
  updated_at = now();

-- 4. Sections
ON CONFLICT (id) DO UPDATE SET
  name = excluded.name,
  updated_at = now();

-- 5. Subjects
ON CONFLICT (id) DO UPDATE SET
  name = excluded.name,
  code = excluded.code,
  updated_at = now();

-- 6. App Users (1 Admin, 5 Teachers, 10 Students)
ON CONFLICT (id) DO UPDATE SET
  neon_user_id = excluded.neon_user_id,
  email = excluded.email,
  display_name = excluded.display_name,
  is_active = true,
  updated_at = now();

-- 7. Staff (Admin & 5 Teachers)
ON CONFLICT (id) DO UPDATE SET
  user_id = excluded.user_id,
  full_name = excluded.full_name,
  email = excluded.email,
  phone = excluded.phone,
  is_teacher = excluded.is_teacher,
  updated_at = now();

-- 8. Link Section Class Teachers
UPDATE sections SET class_teacher_staff_id = '10000000-0000-4000-8000-000000000302' WHERE id = '10000000-0000-4000-8000-000000000501'; -- 6A -> Priya Menon
UPDATE sections SET class_teacher_staff_id = '10000000-0000-4000-8000-000000000303' WHERE id = '10000000-0000-4000-8000-000000000503'; -- 7A -> Arjun Rao
UPDATE sections SET class_teacher_staff_id = '10000000-0000-4000-8000-000000000304' WHERE id = '10000000-0000-4000-8000-000000000505'; -- 8A -> Sara Iyer

-- 9. Teacher Assignments
ON CONFLICT (id) DO UPDATE SET
  can_take_daily_attendance = excluded.can_take_daily_attendance,
  updated_at = now();

-- 10. Students (10 Demo Students)
ON CONFLICT (id) DO UPDATE SET
  user_id = excluded.user_id,
  full_name = excluded.full_name,
  guardian_name = excluded.guardian_name,
  guardian_phone = excluded.guardian_phone,
  is_active = excluded.is_active,
  updated_at = now();

-- 11. Student Enrollments
ON CONFLICT (id) DO UPDATE SET
  class_id = excluded.class_id,
  section_id = excluded.section_id,
  roll_number = excluded.roll_number,
  updated_at = now();

-- 12. Fee Structures & Allocations
ON CONFLICT (id) DO UPDATE SET
  amount = excluded.amount,
  due_date = excluded.due_date,
  updated_at = now();

COMMIT;
